 [Serializable] public sealed class NativeAppearanceConfiguration {public string gameRoot,python,packages,cacheDirectory;}
 [Serializable] public sealed class NativeAppearanceProgress {public float progress;public string message;}
 public sealed class RebirthNativeAppearanceImport : IDisposable {
  public static string ConfigurationPath=>Path.GetFullPath("ProjectSettings/RebirthNativeAppearance.json");
  public static NativeAppearanceConfiguration Configuration(){if(File.Exists(ConfigurationPath))return JsonUtility.FromJson<NativeAppearanceConfiguration>(File.ReadAllText(ConfigurationPath));var result=new NativeAppearanceConfiguration{python=RebirthFaceImageJob.ReadConfiguration()?.python};if(!string.IsNullOrEmpty(result.python)){var dir=new DirectoryInfo(Path.GetDirectoryName(result.python));for(int i=0;i<9&&dir!=null;i++,dir=dir.Parent){if(Directory.Exists(Path.Combine(dir.FullName,"AssetBundle",".python")))result.packages=Path.Combine(dir.FullName,"AssetBundle",".python");if(Directory.Exists(Path.Combine(dir.FullName,"7DaysToDie_Data")))result.gameRoot=dir.FullName;}}return result;}
  public static void Save(NativeAppearanceConfiguration config){File.WriteAllText(ConfigurationPath,JsonUtility.ToJson(config,true));}
  Process process;NativeAppearanceConfiguration config;string output,stderr="";DateTime start=DateTime.UtcNow;
  public bool Finished {get;private set;}public string Error {get;private set;}public string Status {get;private set;}="Preparing native appearance import";public float Progress {get;private set;}public double ElapsedSeconds=>(DateTime.UtcNow-start).TotalSeconds;
  static string Quote(string value){if(value==null||value.IndexOfAny(new[]{'"','\r','\n'})>=0)throw new ArgumentException("Invalid native import path.");return "\""+value+"\"";}
  public RebirthNativeAppearanceImport(){config=Configuration();string backend=AssetDatabase.FindAssets("native_appearance_importer").Select(AssetDatabase.GUIDToAssetPath).FirstOrDefault(p=>p.EndsWith("/native_appearance_importer.py",StringComparison.Ordinal));if(!File.Exists(config.python)||!Directory.Exists(config.packages)||!Directory.Exists(Path.Combine(config.gameRoot??"","Data","Addressables","Standalone"))||backend==null)throw new FileNotFoundException("Configure the game folder, local Python and Unity asset-inspection packages before importing native appearance.");output=Path.GetFullPath("Library/RebirthNativeAppearance/"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(output);var info=new ProcessStartInfo(config.python,Quote(Path.GetFullPath(backend))+" --game "+Quote(config.gameRoot)+" --output "+Quote(output)){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true};info.EnvironmentVariables["PYTHONPATH"]=config.packages;process=new Process{StartInfo=info};process.OutputDataReceived+=(s,e)=>{};process.ErrorDataReceived+=(s,e)=>{if(e.Data!=null)lock(this)stderr=(stderr+e.Data+"\n").Substring(Math.Max(0,stderr.Length+e.Data.Length+1-12000));};process.Start();process.BeginOutputReadLine();process.BeginErrorReadLine();}
  public void Poll(){if(Finished)return;string path=Path.Combine(output,"progress.json");try{if(File.Exists(path)){var state=JsonUtility.FromJson<NativeAppearanceProgress>(File.ReadAllText(path));Progress=state.progress;Status=state.message;}}catch(IOException){}if(!process.HasExited)return;process.WaitForExit();Finished=true;if(process.ExitCode!=0||!File.Exists(Path.Combine(output,"Catalog.json"))){lock(this)Error="Native appearance import failed: "+stderr;Status=Error;return;}config.cacheDirectory=output;Save(config);RebirthNativeAppearanceLibrary.Reload();Progress=1;Status="Native appearance library imported";}
  public void Dispose(){if(process==null)return;if(!process.HasExited)process.Kill();process.Dispose();process=null;}
 }
